"""
Data Models Module - 数据模型定义
==================================
遵循CleanRL原则：单一职责、类型安全

定义所有核心数据结构
"""

from dataclasses import dataclass, field
from typing import List, Dict, Set, Optional, Any
from enum import Enum
import hashlib
import json


class RelationType(str, Enum):
    """关系类型枚举"""
    RELATED = "相关"      # 相关关系
    PROGRESSIVE = "递进"  # 递进关系
    DEPENDENT = "依赖"    # 依赖关系

    @classmethod
    def is_valid(cls, relation: str) -> bool:
        return relation in [r.value for r in cls]


@dataclass
class RawChunk:
    """原始分块 - 来自RAGFlow"""
    chunk_id: str
    content: str
    order: int  # 在原文中的顺序
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __hash__(self):
        return hash(self.chunk_id)

    def __eq__(self, other):
        if isinstance(other, RawChunk):
            return self.chunk_id == other.chunk_id
        return False


@dataclass
class CombinedChunk:
    """组合块 - 滑动窗口组合后的块"""
    combined_id: str
    chunk_ids: List[str]  # 包含的原始chunk_id列表
    content: str  # 格式化后的内容
    start_order: int  # 起始顺序
    end_order: int  # 结束顺序

    @staticmethod
    def generate_id(chunk_ids: List[str]) -> str:
        """根据chunk_ids生成唯一ID"""
        content = "_".join(sorted(chunk_ids))
        return hashlib.md5(content.encode()).hexdigest()[:12]


@dataclass
class AdjNode:
    """邻接节点"""
    relation: str  # 关系类型
    node_id: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "relation": self.relation,
            "node_id": self.node_id
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "AdjNode":
        return cls(
            relation=data["relation"],
            node_id=str(data["node_id"])
        )


@dataclass
class GraphNode:
    """图节点"""
    node_id: str
    node_name: str
    chunk_ids: List[str]
    adj_nodes: List[AdjNode] = field(default_factory=list)
    description: Optional[str] = None
    keywords: Optional[List[str]] = None
    chunk_content: Optional[str] = None  # 合并后的chunk内容

    def to_dict(self) -> Dict[str, Any]:
        result = {
            "node_id": self.node_id,
            "node_name": self.node_name,
            "chunk_ids": self.chunk_ids,
            "adj_nodes": [adj.to_dict() for adj in self.adj_nodes]
        }
        if self.description:
            result["description"] = self.description
        if self.keywords:
            result["keywords"] = self.keywords
        if self.chunk_content:
            result["chunk"] = self.chunk_content
        return result

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "GraphNode":
        adj_nodes = [AdjNode.from_dict(adj) for adj in data.get("adj_nodes", [])]
        return cls(
            node_id=str(data["node_id"]),
            node_name=data["node_name"],
            chunk_ids=data.get("chunk_ids", []),
            adj_nodes=adj_nodes,
            description=data.get("description"),
            keywords=data.get("keywords"),
            chunk_content=data.get("chunk")
        )

    @staticmethod
    def generate_node_id(node_name: str, source_id: str = "") -> str:
        """根据节点名称生成唯一ID"""
        content = f"{node_name}_{source_id}"
        return hashlib.md5(content.encode()).hexdigest()[:10]

    @staticmethod
    def merge_node_ids(id1: str, id2: str) -> str:
        """合并两个node_id"""
        combined = f"{id1}_{id2}"
        return hashlib.md5(combined.encode()).hexdigest()[:10]


@dataclass
class KnowledgeGraph:
    """知识图谱"""
    graph_id: str
    nodes: List[GraphNode]
    source_combined_chunk_id: str
    source_chunk_ids: List[str]

    def to_dict(self) -> Dict[str, Any]:
        return {
            "graph_id": self.graph_id,
            "nodes": [node.to_dict() for node in self.nodes],
            "source_combined_chunk_id": self.source_combined_chunk_id,
            "source_chunk_ids": self.source_chunk_ids
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "KnowledgeGraph":
        return cls(
            graph_id=data["graph_id"],
            nodes=[GraphNode.from_dict(n) for n in data["nodes"]],
            source_combined_chunk_id=data["source_combined_chunk_id"],
            source_chunk_ids=data["source_chunk_ids"]
        )

    def get_node_by_name(self, name: str) -> Optional[GraphNode]:
        """按名称查找节点"""
        for node in self.nodes:
            if node.node_name == name:
                return node
        return None

    def get_node_by_id(self, node_id: str) -> Optional[GraphNode]:
        """按ID查找节点"""
        for node in self.nodes:
            if node.node_id == node_id:
                return node
        return None

    def get_all_node_names(self) -> Set[str]:
        """获取所有节点名称"""
        return {node.node_name for node in self.nodes}


@dataclass
class MergedGraph:
    """合并后的完整图谱"""
    nodes: List[GraphNode]
    name_to_node_id: Dict[str, str]  # 节点名称到ID的映射

    def to_dict(self) -> Dict[str, Any]:
        return {
            "nodes": [node.to_dict() for node in self.nodes],
            "name_to_node_id": self.name_to_node_id
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "MergedGraph":
        return cls(
            nodes=[GraphNode.from_dict(n) for n in data["nodes"]],
            name_to_node_id=data["name_to_node_id"]
        )


@dataclass
class PipelineState:
    """Pipeline状态 - 用于断点续传"""
    current_step: str = "init"
    raw_chunks: List[RawChunk] = field(default_factory=list)
    chunk_id_to_order: Dict[str, int] = field(default_factory=dict)
    combined_chunks: List[CombinedChunk] = field(default_factory=list)
    extracted_graphs: List[KnowledgeGraph] = field(default_factory=list)
    merged_graphs: List[KnowledgeGraph] = field(default_factory=list)
    final_graph: Optional[MergedGraph] = None
    completed_steps: List[str] = field(default_factory=list)
    error_info: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "current_step": self.current_step,
            "raw_chunks": [
                {"chunk_id": c.chunk_id, "content": c.content, 
                 "order": c.order, "metadata": c.metadata}
                for c in self.raw_chunks
            ],
            "chunk_id_to_order": self.chunk_id_to_order,
            "combined_chunks": [
                {"combined_id": c.combined_id, "chunk_ids": c.chunk_ids,
                 "content": c.content, "start_order": c.start_order, 
                 "end_order": c.end_order}
                for c in self.combined_chunks
            ],
            "extracted_graphs": [g.to_dict() for g in self.extracted_graphs],
            "merged_graphs": [g.to_dict() for g in self.merged_graphs],
            "final_graph": self.final_graph.to_dict() if self.final_graph else None,
            "completed_steps": self.completed_steps,
            "error_info": self.error_info
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "PipelineState":
        raw_chunks = [
            RawChunk(chunk_id=c["chunk_id"], content=c["content"],
                    order=c["order"], metadata=c.get("metadata", {}))
            for c in data.get("raw_chunks", [])
        ]
        combined_chunks = [
            CombinedChunk(combined_id=c["combined_id"], chunk_ids=c["chunk_ids"],
                         content=c["content"], start_order=c["start_order"],
                         end_order=c["end_order"])
            for c in data.get("combined_chunks", [])
        ]
        extracted_graphs = [
            KnowledgeGraph.from_dict(g) for g in data.get("extracted_graphs", [])
        ]
        merged_graphs = [
            KnowledgeGraph.from_dict(g) for g in data.get("merged_graphs", [])
        ]
        final_graph = None
        if data.get("final_graph"):
            final_graph = MergedGraph.from_dict(data["final_graph"])

        return cls(
            current_step=data.get("current_step", "init"),
            raw_chunks=raw_chunks,
            chunk_id_to_order=data.get("chunk_id_to_order", {}),
            combined_chunks=combined_chunks,
            extracted_graphs=extracted_graphs,
            merged_graphs=merged_graphs,
            final_graph=final_graph,
            completed_steps=data.get("completed_steps", []),
            error_info=data.get("error_info")
        )

